418→         // Helper: wrap operation with event emission + error handling
419→         private async withOperation<T>(name: string, fn: () => Promise<T>): Promise<T> {
420→           const start = Date.now();
421→           this.config.onOperationStart?.(name);
422→           this.emitter.emit({ type: 'operation:start', operation: name });
423→           try {
